-- Depends on 20260922000000_milestone1_financial_foundation. All records are additive.
ALTER TABLE "RepaymentSchedule" ADD COLUMN "scheduleVersionId" TEXT, ADD COLUMN "supersededAt" TIMESTAMP(3);
CREATE TABLE "LoanRefinance" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "sourceLoanId" TEXT NOT NULL, "newLoanId" TEXT NOT NULL, "settlementAmount" DECIMAL(12,2) NOT NULL, "additionalDisbursement" DECIMAL(12,2) NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LoanRefinance_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "LoanRefinance_sourceLoanId_key" ON "LoanRefinance"("sourceLoanId"); CREATE UNIQUE INDEX "LoanRefinance_newLoanId_key" ON "LoanRefinance"("newLoanId"); CREATE INDEX "LoanRefinance_organizationId_idx" ON "LoanRefinance"("organizationId"); ALTER TABLE "LoanRefinance" ADD CONSTRAINT "LoanRefinance_sourceLoanId_fkey" FOREIGN KEY ("sourceLoanId") REFERENCES "Loan"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "LoanRefinance" ADD CONSTRAINT "LoanRefinance_newLoanId_fkey" FOREIGN KEY ("newLoanId") REFERENCES "Loan"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "LoanScheduleVersion" ("id" TEXT NOT NULL, "loanId" TEXT NOT NULL, "version" INTEGER NOT NULL, "reason" TEXT NOT NULL, "effectiveDate" DATE NOT NULL, "schedule" JSONB NOT NULL, "createdById" TEXT NOT NULL, "approvedById" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LoanScheduleVersion_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "LoanScheduleVersion_loanId_version_key" ON "LoanScheduleVersion"("loanId", "version"); CREATE INDEX "LoanScheduleVersion_loanId_effectiveDate_idx" ON "LoanScheduleVersion"("loanId", "effectiveDate"); ALTER TABLE "LoanScheduleVersion" ADD CONSTRAINT "LoanScheduleVersion_loanId_fkey" FOREIGN KEY ("loanId") REFERENCES "Loan"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "RepaymentSchedule" ADD CONSTRAINT "RepaymentSchedule_scheduleVersionId_fkey" FOREIGN KEY ("scheduleVersionId") REFERENCES "LoanScheduleVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "LoanRestructure" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "loanId" TEXT NOT NULL, "scheduleVersionId" TEXT NOT NULL, "reason" TEXT NOT NULL, "effectiveDate" DATE NOT NULL, "createdById" TEXT NOT NULL, "approvedById" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LoanRestructure_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "LoanRestructure_scheduleVersionId_key" ON "LoanRestructure"("scheduleVersionId"); CREATE INDEX "LoanRestructure_organizationId_loanId_idx" ON "LoanRestructure"("organizationId", "loanId"); ALTER TABLE "LoanRestructure" ADD CONSTRAINT "LoanRestructure_loanId_fkey" FOREIGN KEY ("loanId") REFERENCES "Loan"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "LoanRestructure" ADD CONSTRAINT "LoanRestructure_scheduleVersionId_fkey" FOREIGN KEY ("scheduleVersionId") REFERENCES "LoanScheduleVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "LoanWriteOff" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "loanId" TEXT NOT NULL, "writtenOffPrincipal" DECIMAL(12,2) NOT NULL, "writtenOffInterest" DECIMAL(12,2) NOT NULL, "writtenOffPenalty" DECIMAL(12,2) NOT NULL DEFAULT 0, "reason" TEXT NOT NULL, "approvedById" TEXT NOT NULL, "approvedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LoanWriteOff_pkey" PRIMARY KEY ("id")); CREATE INDEX "LoanWriteOff_organizationId_loanId_idx" ON "LoanWriteOff"("organizationId", "loanId"); ALTER TABLE "LoanWriteOff" ADD CONSTRAINT "LoanWriteOff_loanId_fkey" FOREIGN KEY ("loanId") REFERENCES "Loan"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "WriteOffRecovery" ("id" TEXT NOT NULL, "writeOffId" TEXT NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "recoveredAt" DATE NOT NULL, "note" TEXT, "collectedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WriteOffRecovery_pkey" PRIMARY KEY ("id")); CREATE INDEX "WriteOffRecovery_writeOffId_recoveredAt_idx" ON "WriteOffRecovery"("writeOffId", "recoveredAt"); ALTER TABLE "WriteOffRecovery" ADD CONSTRAINT "WriteOffRecovery_writeOffId_fkey" FOREIGN KEY ("writeOffId") REFERENCES "LoanWriteOff"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
